fn plan(task: str) -> DslQuery:
  pattern = 'Fallback'
  chain = [Agent('mcp-integration-wizard'), Agent('practical-programmer'), Agent('docs-generator')]
  dsl = Fallback(chain).with_prompt(task)
  for i, agent in enumerate(chain):
    outcome = try_run(agent, task, budget=token_budget(i))
    if outcome.ok:
      return dsl.with_winner(i)
  assert typecheck(dsl).valid
  return dsl

